
from taf.vran.vdu.enb.rest.exceptions import APIRequestError
from taf.vran.vdu.enb.rest.releases.base_ltevdu import BaseLTEvDU


class LTEvDU26R1(BaseLTEvDU):
    """
    LTEvDU26R1 class for LTE vDU release 26R1.
    This class is a subclass of BaseLTEvDU and provides specific functionality
    for the LTE vDU release 26R1.
    """
